INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "晚唐至五代", "birth_year": 852, "death_year": 912, "description": "朱温，后赐名朱全忠，又名朱晃，后梁建立者。籍贯宋州砀山午沟里；父亲朱诚以《五经》教授乡里，父亡后家贫，与母亲、兄长在萧县刘崇家佣食。877年随兄朱存加入黄巢军，882年归唐并获赐名全忠，883年入镇汴州。907年称帝，912年在宫廷政变中被杀。", "biography": "朱温，后赐名朱全忠，又名朱晃，后梁建立者。籍贯宋州砀山午沟里；父亲朱诚以《五经》教授乡里，父亡后家贫，与母亲、兄长在萧县刘崇家佣食。877年随兄朱存加入黄巢军，882年归唐并获赐名全忠，883年入镇汴州。907年称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温、朱全昱、朱存之父，以《五经》教授乡里。", "biography": "朱温、朱全昱、朱存之父，以《五经》教授乡里。", "status": "draft", "id": "e27f812b-f91f-544d-9e6d-b6a3076c8ed8"}, {"name": "王氏（朱温母）", "aliases": ["文惠王皇后"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温之母，姓王氏；丈夫去世后携子寄居萧县刘崇家。", "biography": "朱温之母，姓王氏；丈夫去世后携子寄居萧县刘崇家。", "status": "draft", "id": "2cc6ea51-f5b6-5f59-b130-1ed2810802cd"}, {"name": "朱全昱", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱温在即位前更名晃”中为质问者。", "biography": null, "status": "draft", "id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5"}, {"name": "朱存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温兄长，877年与朱温一同加入黄巢军。", "biography": "朱温兄长，877年与朱温一同加入黄巢军。", "status": "draft", "id": "10fcda56-9e52-5fea-a527-02005093150b"}, {"name": "刘崇", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "萧县人。朱温父亲去世后，朱温一家在其家佣食。", "biography": "萧县人。朱温父亲去世后，朱温一家在其家佣食。", "status": "draft", "id": "94884c4d-944d-5ab8-9444-5364c194c6d7"}, {"name": "黄巢", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "biography": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "status": "draft", "id": "f1a6e500-8866-5790-8423-7db3ce39a131"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "胡真", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温亲将，882年与谢瞳劝朱温归唐。", "biography": "朱温亲将，882年与谢瞳劝朱温归唐。", "status": "draft", "id": "091ba320-f158-5b07-9a25-feebc1f0e200"}, {"name": "谢瞳", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "福州人，朱温亲将；882年劝朱温归唐，后奉表赴唐帝行在。", "biography": "福州人，朱温亲将；882年劝朱温归唐，后奉表赴唐帝行在。", "status": "draft", "id": "19a95900-a43a-5460-aa4a-1f3667da346e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱温出生于砀山午沟里", "start_year": 852, "end_year": 852, "time_original": "唐大中六年十月二十一日", "dynasty": "唐", "description": "《旧五代史》记朱温生于唐大中六年（852）十月二十一日，出生地为砀山县午沟里。", "phases": [], "location_name": "砀山县午沟里", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "a562475d-ab49-562d-a253-69efcda4390c"}, {"title": "朱温与兄朱存加入黄巢军", "start_year": 877, "end_year": 877, "time_original": "唐乾符四年", "dynasty": "唐", "description": "《新五代史》记乾符四年（877），朱存、朱温加入黄巢军。该年是本批采用的入军纪年，不据该段认定黄巢也在877年才起兵。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "7005b575-fc48-58ba-b31b-e6fcc6e8389e"}, {"title": "朱温屯东渭桥并招降诸葛爽", "start_year": 880, "end_year": 880, "time_original": "唐广明元年十二月", "dynasty": "唐", "description": "黄巢命朱温屯东渭桥，并令其劝降诸葛爽，诸葛爽随后归降黄巢。", "phases": [], "location_name": "东渭桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "790fd3f7-afe8-5fd7-8ef0-e9f5b74b6b5d"}, {"title": "朱温任先锋使进攻南阳", "start_year": 881, "end_year": 881, "time_original": "唐中和元年二月", "dynasty": "唐", "description": "黄巢任朱温为东南面行营先锋使，令其攻取南阳；《旧五代史》记其攻下南阳。", "phases": [], "location_name": "南阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "f18a82d0-917e-5210-9ae6-73105710f682"}, {"title": "朱温攻占同州", "start_year": 882, "end_year": 882, "time_original": "唐中和二年二月", "dynasty": "唐", "description": "黄巢命朱温自行攻取同州。二月，同州刺史米诚奔河中，朱温占据同州。", "phases": [], "location_name": "同州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "6af8b69c-1d8a-5189-b7e6-ab269102a4ea"}, {"title": "朱温举同州归唐", "start_year": 882, "end_year": 882, "time_original": "唐中和二年九月丙戌", "dynasty": "唐", "description": "朱温求援受阻，见黄巢势衰；胡真、谢瞳劝其归唐。朱温杀监军严实，举同州归降王重荣，谢瞳随后奉表赴行在。", "phases": [], "location_name": "同州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "1d54c35d-8b82-53ed-9c64-12856e9c8de3"}, {"title": "唐廷赐朱温名全忠", "start_year": 882, "end_year": 882, "time_original": "唐中和二年冬十月条", "dynasty": "唐", "description": "唐廷授朱温河中行营招讨副使等官职，赐名全忠。朱温与朱全忠为同一人。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "ccf33971-96e6-554c-a267-da0e6739a537"}, {"title": "朱全忠获任宣武节度使", "start_year": 883, "end_year": 883, "time_original": "唐中和三年三月己丑", "dynasty": "唐", "description": "唐廷任朱全忠为宣武节度使，令其待收复长安后赴镇。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "7fbe71f2-da76-58fa-87c2-2b055fe24092"}, {"title": "朱全忠入镇汴州", "start_year": 883, "end_year": 883, "time_original": "唐中和三年秋七月丁卯", "dynasty": "唐", "description": "朱全忠率所部数百人赴镇，于七月丁卯到达汴州。当时汴、宋饥荒，公私困乏，军队难制且受外敌威胁。", "phases": [], "location_name": "汴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "保留史载地名，未做坐标校准。", "status": "draft", "id": "c8676ba0-4c0e-5bca-8ce6-00fb8efb162d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

