INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "biography", "claim_text": "朱温籍贯宋州砀山午沟里；父朱诚教授《五经》，父亡后家贫，随母兄在刘崇家佣食。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "01238033-e16a-5180-bbf7-fec4f887c045", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "birth_year", "claim_text": "朱温生于852年，原纪年为唐大中六年十月二十一日。", "citation": "卷一·梁太祖纪一", "note": "原文：以唐大中六年嵗在壬申，十月二十一日夜，生于碭山縣午溝里。；核对说明：年号换算为852年；十月二十一日保留为传统历日，不换算公历月日。旧五代史此卷为清代辑佚本。", "status": "draft", "id": "bb75e3f8-78ec-5504-8426-256a6503fa74", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱温、朱全昱、朱存之父，以《五经》教授乡里。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "51c02b25-59de-5f95-9519-39eeb26ed06f", "subject_id": "e27f812b-f91f-544d-9e6d-b6a3076c8ed8", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱温之母，姓王氏；丈夫去世后携子寄居萧县刘崇家。", "citation": "卷一·梁太祖纪一", "note": "原文：帝卽誠之第三子，母曰文惠王皇后。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "b07af2ce-b658-5547-8fed-2641566aa647", "subject_id": "2cc6ea51-f5b6-5f59-b130-1ed2810802cd", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "person", "field_path": "biography", "claim_text": "王氏丧夫后携子寄居刘崇家。", "citation": "卷二百五十四·唐纪七十", "note": "原文：温少孤贫，与兄昱、存随母王氏依萧县刘崇家，；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "8e1792d2-0c15-5bfc-a886-08a056a96383", "subject_id": "2cc6ea51-f5b6-5f59-b130-1ed2810802cd", "source_id": "e7ae14a4-89e0-5664-a254-8286b13c957c"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱诚长子、朱温兄长，早年与母亲、兄弟在刘崇家佣食。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "76d95da9-1048-57a4-bac6-b814a114b517", "subject_id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱温兄长，877年与朱温一同加入黄巢军。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：唐僖宗乾符四年，黄巢起曹、濮，存、温亡入贼中。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "f88fea49-c16e-5d3c-8387-f860b620bce3", "subject_id": "10fcda56-9e52-5fea-a527-02005093150b", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱存是朱诚之子、朱温兄长。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "3c7cc64f-e62a-52da-bd37-d31792a75a35", "subject_id": "10fcda56-9e52-5fea-a527-02005093150b", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "biography", "claim_text": "萧县人。朱温父亲去世后，朱温一家在其家佣食。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "283d23a9-2b2d-51aa-a7cd-49d88c9eed89", "subject_id": "94884c4d-944d-5ab8-9444-5364c194c6d7", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person", "field_path": "biography", "claim_text": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "citation": "卷二百五十四·唐纪七十", "note": "原文：诸葛爽以工北行营兵顿栎阳，黄巢将砀山硃温屯东渭桥，巢使温诱说之，爽遂降于巢。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "e521e1e6-d97d-54d4-8d7f-81b3ad4793bd", "subject_id": "f1a6e500-8866-5790-8423-7db3ce39a131", "source_id": "e7ae14a4-89e0-5664-a254-8286b13c957c"}, {"subject_table": "person", "field_path": "biography", "claim_text": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "citation": "卷一·梁太祖纪一", "note": "原文：時河中節度使王重榮屯兵數萬，糾兵諸侯，以圖興復。帝時與之鄰封，屢為重榮所敗，遂請濟師于巢。表章十上，為偽左軍使孟楷所蔽，不達。又聞巢軍勢蹙，諸校離心，帝知其必敗。九月，帝遂與左右定計，斬偽監軍使嚴實，嚴實原書訛作「嚴貴」，今據歐陽史及通鑑改正。 舉郡降于重榮。案舊唐書僖宗紀：八月庚子，賊同州防禦使朱溫殺其監軍嚴實，與大將胡真、謝瞳等來降。薛史作九月，與舊唐書異。考新唐書：九月丙戌，黃巢將朱溫以同州降。通鑑亦作九月丙戌，朱溫殺其監軍嚴實，舉州降。皆與薛史同。是朱溫之降，實在九月，舊唐書誤。重榮卽日飛章上奏，；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "9627c9bc-58d5-5ad3-9479-2caf4de79285", "subject_id": "fc935d86-e44a-538d-b21b-6e28a8604116", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "person", "field_path": "biography", "claim_text": "朱温亲将，882年与谢瞳劝朱温归唐。", "citation": "卷二百五十五·唐纪七十一", "note": "原文：黄巢所署同州防御使硃温屡请益兵以扞河中，知右军事孟楷抑之，不报。温见巢兵势日蹙，知其将亡，亲将胡真、谢瞳劝温归国。九月，丙戌，温杀其监军严实，举州降王重荣。温以舅事重荣，王鐸承制以温为同华节度使，使瞳奉表诣行在。瞳，福州人也。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "1b7497e6-8615-5f74-a266-8d307fb8ac23", "subject_id": "091ba320-f158-5b07-9a25-feebc1f0e200", "source_id": "da7ef52b-1f83-5062-9ee2-9a4ba60c2c41"}, {"subject_table": "person", "field_path": "biography", "claim_text": "福州人，朱温亲将；882年劝朱温归唐，后奉表赴唐帝行在。", "citation": "卷二百五十五·唐纪七十一", "note": "原文：黄巢所署同州防御使硃温屡请益兵以扞河中，知右军事孟楷抑之，不报。温见巢兵势日蹙，知其将亡，亲将胡真、谢瞳劝温归国。九月，丙戌，温杀其监军严实，举州降王重荣。温以舅事重荣，王鐸承制以温为同华节度使，使瞳奉表诣行在。瞳，福州人也。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "e2cce5f0-c808-5a8e-9302-c30d9abbbdf5", "subject_id": "19a95900-a43a-5460-aa4a-1f3667da346e", "source_id": "da7ef52b-1f83-5062-9ee2-9a4ba60c2c41"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "朱诚为朱温之父。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "63dde52f-d833-5ba2-81a1-99818d4eca7a", "subject_id": "d09307b2-c689-52fd-a70a-e63e9b86a3e0", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "王氏为朱温之母，史书称文惠王皇后。", "citation": "卷一·梁太祖纪一", "note": "原文：帝卽誠之第三子，母曰文惠王皇后。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "bd6656f1-d8f0-5397-a603-4173c2fd76c8", "subject_id": "24768220-271f-57f0-a400-4133d7992596", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "朱全昱为朱温兄长。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "a56a115f-c903-5a0b-a704-0b0f4330d83e", "subject_id": "25262d71-7aa3-5bf2-b9a6-8a7a408ffca4", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "朱存为朱温兄长。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：太祖神武元圣孝皇帝，姓硃氏，宋州砀山午沟里人也。其父诚，以《五经》教授乡里，生三子，曰全昱、存、温。诚卒，三子贫，不能为生，与其母佣食萧县人刘崇家。全昱无他材能，然为人颇长者。存、温勇有力，而温尤凶悍。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "8dad9781-6138-5ee0-9cf2-f60a53407d40", "subject_id": "11f80f11-722c-52ab-a87e-2af778a31d92", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "朱温早年为黄巢部将；此关系限于归唐前，不表示终身效忠。", "citation": "卷二百五十四·唐纪七十", "note": "原文：诸葛爽以工北行营兵顿栎阳，黄巢将砀山硃温屯东渭桥，巢使温诱说之，爽遂降于巢。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "d2a5ab08-f7cd-54e2-93ac-33834d19c6f2", "subject_id": "71b47f69-7acb-511a-b629-e3192afcc604", "source_id": "e7ae14a4-89e0-5664-a254-8286b13c957c"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记朱温生于唐大中六年（852）十月二十一日，出生地为砀山县午沟里。", "citation": "卷一·梁太祖纪一", "note": "原文：以唐大中六年嵗在壬申，十月二十一日夜，生于碭山縣午溝里。；核对说明：按所属年条定位；原历月日未换算为公历。", "status": "draft", "id": "e02f0639-f670-5246-8ea0-39e2ce5f1a94", "subject_id": "a562475d-ab49-562d-a253-69efcda4390c", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：出生。", "citation": "卷一·梁太祖纪一", "note": "原文：以唐大中六年嵗在壬申，十月二十一日夜，生于碭山縣午溝里。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "9c2a814d-918b-52ed-a020-052a57f8f745", "subject_id": "2b7ba5ac-1049-5f5f-a9a9-7c6393a1c195", "source_id": "02fe9701-db4d-5c90-9179-b1868c7b778a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》记乾符四年（877），朱存、朱温加入黄巢军。该年是本批采用的入军纪年，不据该段认定黄巢也在877年才起兵。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：唐僖宗乾符四年，黄巢起曹、濮，存、温亡入贼中。；核对说明：入军年采用新五代史乾符四年；旧五代史仅记乾符中，不能作为877年的独立确认。曹、濮是段中黄巢起兵背景地，非确定入军地点。", "status": "draft", "id": "a373493b-9849-51c9-a2d3-feba8d23aa0f", "subject_id": "7005b575-fc48-58ba-b31b-e6fcc6e8389e", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：加入黄巢军。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：唐僖宗乾符四年，黄巢起曹、濮，存、温亡入贼中。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "28524782-8fb3-5dd7-87b1-527e2f968795", "subject_id": "95f29c76-0534-5c26-b3d2-a195c7fd39d9", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱存：加入黄巢军。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：唐僖宗乾符四年，黄巢起曹、濮，存、温亡入贼中。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "5c8c9d2f-3026-5b17-82ec-e8f8f9bb9803", "subject_id": "04354b0b-138c-5682-98c5-6a55dc77e679", "source_id": "9830cf06-be52-523f-b057-567426bcc65d"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "黄巢：军队首领。", "citation": "卷一·梁本纪第一；PDF第1—3页", "note": "原文：唐僖宗乾符四年，黄巢起曹、濮，存、温亡入贼中。；核对说明：按原文陈述，不补入原文未载的日期或细节。", "status": "draft", "id": "0fc159a7-7f25-5173-a2bb-5004ac58121e", "subject_id": "77494e5f-800c-54e2-bb45-48a233432f3e", "source_id": "9830cf06-be52-523f-b